INSERT OR REPLACE INTO lab_topics (id, chapter_id, title, content, created_at) VALUES 
('t01', 'chap-01', 'The Anatomy of Spear Phishing', 'Unlike traditional bulk phishing, spear phishing is a highly targeted attack directed at a specific individual or organization. Threat actors use OSINT from social media to craft alarming, highly personalized emails. A classic spear phishing bait relies on manufacturing urgency—like spoofing a direct manager''s urgent payment request—bypassing the victim''s natural skepticism.', 1711730000),
('t02', 'chap-01', 'Pretexting & Authority Impersonation', 'Pretexting occurs when an attacker fabricates an elaborate scenario to steal sensitive data. Rather than just asking for a password, the attacker establishes trust by impersonating authority figures—such as the IT Helpdesk. They leverage our instinctual deference to authority, often referencing authentic internal company jargon intercepted through prior reconnaissance.', 1711730001),
('t03', 'chap-01', 'Typosquatting & Homograph Attacks', 'Typosquatting targets users who incorrectly type a website address, while Homograph Attacks utilize visually similar characters (like a Cyrillic "р") to create identical-looking URLs. These malicious domains host pixel-perfect cloned login pages designed strictly for credential harvesting because standard browser warnings frequently fail to trigger.', 1711730002),
('t04', 'chap-01', 'The Evil Twin: Rogue Access Points', 'An Evil Twin attack involves a hacker setting up a fraudulent Wi-Fi access point designed to mimic a legitimate network. When a victim connects to the rogue AP, the attacker executes a Man-in-the-Middle position, passively sniffing unencrypted traffic or aggressively injecting captive portals to harvest credentials.', 1711730003),
('t05', 'chap-01', 'Quishing: QR Code Threats', 'Quishing exploits the inability of the human eye to parse the destination URL embedded inside a QR code. Attackers physically slap malicious QR stickers over legitimate payment codes. Once scanned, the victim''s mobile device is silently redirected to a credential harvesting portal or stealth malware download.', 1711730004),
('t06', 'chap-01', 'Whaling: The C-Suite Compromise', 'Whaling is a specialized subset of spear phishing that exclusively targets high-profile executives like CEOs or CFOs. Attackers research executive schedules to draft highly sophisticated emails carrying malicious attachments. Combating whaling requires implementing strict Out-of-Band internal verification protocols for all high-value wire transfers.', 1711730005),
('t07', 'chap-01', 'Vishing & Deepfake Audio Spoofing', 'Utilizing Artificial Intelligence, threat actors can map an executive''s voice using seconds of public audio. They deploy this synthesized Deepfake audio live over VoIP calls, issuing urgent, convincing verbal directives to fearful junior employees, bypassing standard email security gateways entirely.', 1711730006),
('t08', 'chap-01', 'Baiting Tactics & USB Drops', 'Baiting preys on human curiosity through malicious USB drops. Attackers scatter malware-laden flash drives in corporate lobbies labeled "Executive Salaries." When an unsuspecting employee plugs the drive into a workstation, it immediately executes a hidden reverse shell payload enumerating the internal network.', 1711730007),
('t09', 'chap-01', 'OSINT & Reconnaissance', 'Before attacking, threat actors meticulously scrape LinkedIn profiles and public forums to construct extensive behavioral profiles. They identify the target''s software stack, hobbies, and direct superiors. This silent intelligence dramatically increases the success rate of subsequent phishing payloads by anchoring them in undeniable reality.', 1711730008),
('t10', 'chap-01', 'Defending Against the Human Element', 'The human remains the most vulnerable node in any cybersecurity architecture. Modern defense requires continuous, behavioral microlearning and simulated phishing campaigns designed to build cognitive muscle memory, along with a "No-Blame" reporting culture prioritizing rapid incident notification.', 1711730009),

('t11', 'chap-02', 'Symmetric vs Asymmetric Payload Encryption', 'Ransomware utilizes hybrid cryptography. It generates a unique Symmetric key locally to execute the high-speed encryption of files. It then utilizes an Asymmetric public key, hardcoded into the malware, to securely encrypt the Symmetric key, making recovery impossible without paying for the Private Key.', 1711730010),
('t12', 'chap-02', 'The Anatomy of Double Extortion', 'Before encrypting databases, the threat actor operates silently on the network for weeks, exfiltrating terabytes of highly sensitive intellectual property to an offshore server. If the victim attempts to restore from backups and refuses the ransom, the attacker threatens to leak the raw stolen data on the Dark Web.', 1711730011),
('t13', 'chap-02', 'Understanding Ransomware as a Service (RaaS)', 'Ransomware has adopted a SaaS business model. Elite cybercriminal cartels handle the complex malware development and payment negotiation. They lease this infrastructure to "Affiliates" who specialize merging in breaching perimeters. When an Affiliate infects a target, the cartel automatically splits the cryptocurrency profit.', 1711730012),
('t14', 'chap-02', 'Initial Access Brokers (IAB)', 'Initial Access Brokers are specialized mercenaries who silently compromise corporate perimeters via exposed RDP ports or stolen session cookies. Once they obtain persistent administrative access, they auction this access on the Dark Web to ransomware affiliates, drastically accelerating the payload timeline.', 1711730013),
('t15', 'chap-02', 'Lateral Movement & AD Compromise', 'Upon breaching a workstation, the attacker''s primary objective is Lateral Movement. They utilize tools like Mimikatz to scrape local memory, silently escalating privileges until they achieve Domain Admin status within Active Directory, enabling them to push the ransomware payload natively via Group Policy.', 1711730014),
('t16', 'chap-02', 'The Principle of Least Privilege (PoLP)', 'PoLP mandates that users and systems are granted only the absolute minimum baseline access rights necessary. If an employee''s laptop is compromised by an infected PDF, the ransomware executes solely within that user''s limited permission scope, severely crippling its ability to spread.', 1711730015),
('t17', 'chap-02', 'Shadow Copies & Backup Destruction', 'Modern ransomware silently purges Volume Shadow Copies via commands like "vssadmin delete shadows" immediately before payload execution. Advanced variants actively hunt out the network for attached NAS drives, annihilating external backups to ensure the victim faces total, unrecoverable data deletion.', 1711730016),
('t18', 'chap-02', 'Sandbox Evasion & Killswitches', 'To bypass automated behavioral analysis from security researchers, ransomware frequently checks if it''s running in an isolated virtual machine. Historic variants like WannaCry utilized external DNS Killswitches, paradoxically ceasing cryptographic operations the moment a security researcher intercepted the designated beacon traffic.', 1711730017),
('t19', 'chap-02', 'C2 Communication & Beaconing', 'Advanced malware executes "beaconing", repeatedly sending silent, encrypted requests attempting to receive operational commands or exchange encryption keys with a Command and Control server. Threat actors utilize Domain Generation Algorithms, continuously shifting through thousands of random subdomains daily to evade static firewalls.', 1711730018),
('t20', 'chap-02', 'Immutable Backups & The 3-2-1 Rule', 'The ultimate failsafe is offshore immutable backups. Immutability ensures written data is cryptographically locked and read-only, preventing encryption even by Domain Admins. Organizations must enforce the 3-2-1 methodology: 3 copies of data, across 2 different media, with 1 copy strictly air-gapped off-site.', 1711730019);
